	["Achtung, der Gastwirt läuft immer von der einen Seite zur anderen!"] = "Attention : l'aubergiste marche d'un côté à l'autre !",
	["Achtung der Questgeber bewegt sich. Allenfalls beim anderen Wegpunkt suchen!"] = "Attention : le donneur de quête se déplace. Regardez l'autre point de passage !",
	["Achtung, der Weg zur Hauptroute führt an mehreren Bäumlingen Level 52 bis 53"] = "Attention : le chemin vers l'itinéraire principal croise plusieurs créatures de niveau 52 et 53",
	["Kreuzung der Hauptstrasse und dem Weg zur Burg Stromgarde. ... Vorsicht vor dem Kurier der Verlassenen und seiner Leibwache"] = "Croisement de la route principale et du chemin vers le château de Stromgarde. Méfiez-vous de la patrouille du courrier",
	["Hier warten bis die Fahr zu Ende ist !!"] = "Attendez ici jusqu'à la fin du trajet !",
	["Von hier müsst ihr wirklich sehr weit nach Süden schwimmen, bis ein Aufgang/Rampe kommt."] = "D'ici vous devez nager très loin vers le sud jusqu'à atteindre un escalier ou une rampe.",
	["Um den Schlüssel zu diesem Tor zu bekommen, musst du Margol töten und das Horn holen."] = "Pour obtenir la clé de cette grille, vous devez tuer Margol et récupérer la corne.",
	["Gegenstand in Tasche mit rechts anklicken und dann Kristall mit links anklicken!"] = "Clic droit sur l'objet dans votre sac, puis clic gauche sur le cristal !",
	["Achtung hier links ist gleich ein Horde Posten mit Wachen."] = "Attention : sur le côté gauche se trouve une sortie de la Horde avec des gardes.",
	["Achtung: Nach Westen kommt die nächsten 2 Wegpunkte eine extrem schmale Brücke mit Abgrund."] = "Attention : à l'ouest, les 2 prochains points de passage sont sur un pont très étroit.",
	["Umleitung an der Horde vorbei, durch die Wildniss. Vorsicht vor Wildtieren. Ende/Anfang"] = "Détour évitant le camp de la Horde, à travers la nature sauvage. Méfiez-vous des animaux sauvages. Fin/Début",
	["Achtung: hier geht eine Rampe runter. Daher vorsichtig laufen bis zum unteren Punkt."] = "Attention : il y a une rampe qui descend ici. Avancez prudemment jusqu'au point inférieur.",
	["Achtung der Questgeber bewegt sich. Allenfalls beim andern Wegpunkt suchen!"] = "Attention : le donneur de quête se déplace. Trouvez-le à l'autre point de passage s'il n'est pas ici !",
	["Achtung der Questgeber bewegt sich. Allenfalls beim anderen Wegpunkt suchen!"] = "Attention : le donneur de quête se déplace. Trouvez-le à l'autre point de passage s'il n'est pas ici !",
	["Ab diesem Punkt kann man den Weg nicht mehr zurücklaufen!"] = "À partir de ce point, vous ne pourrez plus revenir par où vous êtes venu !",
	["Kreuzung Hauptweg, und der Weg nach Tarrens Mühle und Arathi Hochgebirge ... Achtung! Auf dem Weg von Tarrens Mühle zum Araatchi Hochland läuft der Kurier der Verlassenen mit seiner Leibwache herum. Sehr gefährlich, wenn man nicht bereit ist."] = "Croisement du chemin principal et du chemin vers le Moulin de Tarren et les contreforts d'Arathi. Attention ! Le courrier patrouille entre le Moulin de Tarren et les hautes-terres d'Arathi. Très dangereux.",
	["Achtung: Ab hier genau laufen weiter in die Höhle laufen, da gleich ein grosses Loch in der Mitte ist!"] = "Attention : avancez précisément. Il y a un grand trou au milieu !",
	["Achtung der NPC bewegt sich hier im Kreis!"] = "Attention : le PNJ se déplace en cercle !",
	["Der Erzmagier läuft zwischen den beiden Routenpunkten."] = "L'archimage se déplace entre les deux points de l'itinéraire.",
	["Achtung: nächster Wegpunkt ist der Zeppelin Anleger!"] = "Attention : le prochain point de passage est l'embarcadère du zeppelin !",
	["Achtung die Trollwelpen hier können dich auch zuerst angreifen, wenn du ihnen zu nahe kommst. Da sie Humanoide sind, rennen sie kurz vor dem Sterben weg, So können sie aber auch neue Trolle/Gegner holen. Also Vorsicht!"] = "Attention : les petits trolls vous attaqueront si vous vous approchez trop. Soyez prudent !",
	["Kreuzung vom Hauptweg, und dem Weg nach Süderstade"] = "Croisement du chemin principal et du chemin vers Austrivage",
	["Achtung: Dieser Mob läuft über den ganzen Strand von Norden nach Süden"] = "Attention : cette créature se déplace sur la plage du nord au sud.",
	["Sucht Gammerita zwischen dem südlichem und dem nördlichem Punkt!"] = "Cherchez Gammerita entre le point sud et le point nord !",
	["Achtung: Hier geht eine Rampe hoch. Daher vorsichtig laufen bis zum oberen Punkt."] = "Attention : il y a une rampe qui monte ici. Avancez donc prudemment jusqu'au point supérieur.",
	["Achtung, links ist ein Abgrund. Rechts halten und genau laufen!"] = "Attention : il y a un précipice à gauche. Restez à droite et avancez prudemment !",
	["Brückenkopf Jägerlagerbrücke, Kreuzung zum Jägerlager"] = "Pont de la tête de pont du camp de chasseurs, passage vers le camp de chasseurs",
	["Achtung: Dieser Weg wird meistens von einem Dschungeldonnerer Level 38 verstellt !"] = "Attention : une créature hostile de niveau 38 se trouve sur votre chemin !",
	["Die Rampe zum Glutnebelgipfel vorsichtig rauf laufen!"] = "Montez prudemment la rampe jusqu'au pic de Braise !",
	["Hier auf das Schiff warten, und wenn es angekommen ist, dann zum nächsten Punkt gehen (Schiff)"] = "Attendez le bateau ici. À son arrivée, avancez jusqu'au point suivant (bateau).",
	["Achtung: der Mob bewegt sich über die ganze Karte. -> Am besten sehende Hilfe suchen!"] = "Attention : la créature se déplace partout sur la carte. Faites-vous aider par une personne voyante.",
	["Achtung: Abhang ist rechts. Den Weg zum Questgeber vorsichtig laufen. "] = "Attention : il y a une pente à droite. Avancez prudemment jusqu'au donneur de quête.",
	["Achtung: Nach Osten kommt die nächsten 2 Wegpunkte eine extrem schmale Brücke mit Abgrund."] = "Prudence : les 2 prochains points de passage vers l'est sont sur un pont très étroit.",
	["Vorsicht: Ab hier geht es eine extrem schmale und verwinkelte Rampe ohne Geländer hoch."] = "Attention : d'ici le chemin monte par une rampe extrêmement étroite et sinueuse, sans rambarde.",
	["Ab diesem Punkt ganz besonders vorsichtig laufen!"] = "Avancez très prudemment à partir de ce point !",
	["Achtung: nächster Wegpunkt ist der Zeppelin Anleger!"] = "Attention : le prochain point de passage est l'embarcadère du zeppelin !",
	["Hier Pulver auf den Stein anwenden, dann Mondklaue töten und mit dem Geist von Mondklaue sprechen. (/tar Geist)  "] = "Appliquez la poudre sur la pierre ici. Puis tuez Griffelune et parlez au fantôme de Griffelune. (/tar fantôme)",
	["Vorsicht vor dem Kurier der Verlassenen und seiner Leibwache"] = "Méfiez-vous du courrier et de son garde du corps",
	["Du bist im Käfig gelandet. Willst du wirklich raus ?"] = "Vous avez atterri dans la cage. Voulez-vous vraiment en sortir ?",
	["Vorsicht vor dem Kurier der Verlassenen und seiner Leibwache"] = "Méfiez-vous du courrier et de son garde du corps",
	["Achtung Gefahr von den Todeswachen von Tarrens Mühle, die an diese Kreuzung ran kommen"] = "Attention : danger venant des gardes de la mort du Moulin de Tarren à ce croisement",
	["Turm von Burg Cenarius,... unten (Erdgeschoss)"] = "Tour du château de Cenarius,... en bas (premier étage)",
	["Achtung: Hier musst du mindestens den Ruf \\\"Unfreundlich\\\" bei der Holzschlunderfeste haben!"] = "Attention : vous avez besoin d'au moins le niveau de réputation \"inamical\" avec les Bois-du-Bosquet !",
	["Achtung dieser Übergang wird von der Horde bewacht. Durchgang bei einem defekten Palisadenstück."] = "Attention : ce croisement est gardé par la Horde.",
	["Der Erzmagier läuft zwischen den beiden Routenpunkten."] = "L'archimage se déplace entre les deux points de passage.",
	["Falls ihr ins Wasser fällt, dann nach Gewässer, Unten oder Rettungs Punkt suchen!"] = "Cherchez \"Eaux, en dessous\" ou \"Point de sauvetage\" pour sortir de l'eau !",
	["Achtung: Hier vorsichtig die Rampe rauf laufen!"] = "Attention : montez prudemment la rampe ici !",
	["Sanath ansprechen um nach oben teleportiert zu werden. Oben nach Nyrill suchen!"] = "Parlez à Sanath pour être téléporté. Puis cherchez Nyrill !",
	["Nach der Flamme weiterlaufen und nach dem fallen unten neuen Routenpunkt aufnehmen!"] = "Avancez d'un pas au-delà de la flamme. Après la chute, prenez un nouvel itinéraire !",
	["Der Aufzug wird von der Horde bewacht, gwählt ist der LINKE Aufzug. Beim Anleger warten bist der Aufzug da ist."] = "L'ascenseur est gardé par la Horde. À l'embarcadère, attendez que l'ascenseur soit là.",
	["Kreuzung vom Hauptweg, und dem Weg zur Zuflucht ... Vorsicht vor dem Kurier der Verlassenen und seiner Leibwache"] = "Intersection du chemin principal et du chemin vers le refuge. Méfiez-vous du courrier.",
	["Du bist im Fahrstuhl. Warte bis die Fahrt zu Ende ist!"] = "Vous êtes dans l'ascenseur. Attendez la fin du trajet !",
	["Hier beim Laufen springen um raus zu kommen!"] = "Sautez ici en courant pour sortir !",
	["Achtung: Hier gibt es Räuber Level 4 in der Druchgangshöhle nach Thelsamar Dun Morogh. "] = "Attention : il y a des créatures de niveau 4 sur le chemin vers Thelsamar, Dun Morogh.",
	["Umleitung an der Horde vorbei, durch die Wildniss. Vorsicht vor Wildtieren. Ende/Anfang"] = "Détour évitant la Horde, à travers la nature sauvage. Méfiez-vous des animaux sauvages. Fin/Début",
	["Nyrill ansprechen, um wieder nach unten teleportiert zu werden. "] = "Parlez à Nyrill pour être téléporté vers le bas.",
	["Um rauszugehen laufe auf Sicht zum \\\"Rettung, Punkt,  Höhle, Die blühende Oase, Brachland\\\""] = "Pour sortir, sélectionnez le point de passage \"Sauvetage, Point, Grotte, Oasis de Lavesseau, Brachlande\"",
	["Hier springen um rauf zu kommen !"] = "Sautez ici pour atteindre le point supérieur",
	["Bitte die Translokationskugel benutzen um das Stockwerk zu wechseln"] = "Utilisez la sphère de translocation pour être téléporté.",
	["Ab hier musst du extrem vorsichtig sein. Brücke, Schlucht und Tod lauern."] = "Soyez extrêmement prudent à partir d'ici. Il y a un pont. Ne tombez pas.",
	["rettungspunkt unten schlucht 1"] = "Point de sauvetage au fond du ravin 1",
	["Fahrstuhleingang mitte unten. Bei Route in den Fahrstuhl: Ignoriere den Fahrstuhl einfach. Lauf von hier geradeaus weiter, egal ob der Fahrstuhl da ist. Du fällst eine Etage nach unten und erreichst dort den Fahrstuhleingang unten, von dem du normal die Route weiter läufst. "] = "Entrée de l'ascenseur au milieu inférieur. Si vous suivez un itinéraire vers l'ascenseur : ignorez simplement l'ascenseur. Courez tout droit d'ici, que l'ascenseur soit là ou non. Vous tomberez d'un étage et atteindrez l'entrée de l'ascenseur en bas. Poursuivez l'itinéraire à partir de là.",
	["Vorsicht! Nach Süden geht es über eine schmale Brücke. Nach Osten geh es am Rand einer Schlucht entlang. Nach Norden ist eine sichere Straße."] = "Prudence. Au sud vous traverserez un pont très étroit. À l'est vous longerez le bord d'un ravin. Au nord se trouve une route sûre.",
	["Vorsicht! Ab hier geht es auf diesem Weg im Uhrzeigersinn um eine Schlucht herum. Du läufst am Rand. Präzise laufen!"] = "Prudence. À partir d'ici, cet itinéraire longe le bord d'un ravin. Avancez très précisément !",
	["Achtung: Ab hier zum nächsten Punkt springen!"] = "Attention : d'ici, sautez jusqu'au point suivant !",
	["rettungspunkt unten schlucht"] = "point de sauvetage au fond du ravin",
	["Vorsicht. Extrem schmale Brücke mit Schlucht."] = "Prudence. Pont extrêmement étroit. Ne tombez pas.",
	["Nächster Punkt ist der Fahrstuhleingang. Der Fahrstuhl hat vier Haltestellen: unten, mitte unten, mitte oben, oben. Er macht beim Ankommen ein lautes Knallgeräusch. Beim Abfahren ein Heulgeräusch. Im Fahrstuhl gibt es ein dauerhaftes Maschinengeräusch. Die Maschine befindet sich zwischen Mitte unten und Mitte oben. Lautstärke an den Haltestellen: unten leises Geräusch, mitte unten und mitte oben laut, oben kein Geräusch."] = "Le prochain point de passage est l'entrée de l'ascenseur. L'ascenseur a quatre arrêts : bas, milieu inférieur, milieu supérieur, haut. Il fait un grand bruit de claquement à l'arrivée. Au départ, il fait un bruit de hurlement. Il y a un bruit de machine constant dans l'ascenseur. La machine se trouve entre le milieu inférieur et le milieu supérieur. Volume aux arrêts : bas bruit faible, milieu inférieur et milieu supérieur fort, haut aucun bruit.",
	["Östlicher Ein- und Ausgang Schlucht"] = "Entrée et sortie est du ravin",
	["Hier kommt der Teleportpunkt aus der Höhle zu Haleh. Einfach ab hier ein paar Schritte vorlaufen."] = "Vient ensuite le point de passage de téléportation vers Haleh. Avancez simplement de quelques pas d'ici.",
	["Um den Schlüssel für dieses Tor zu bekommen, musst du Margol töten und das Horn holen."] = "Pour obtenir la clé de cette grille, vous devez tuer Margol et récupérer la corne.",
	["Fahrstuhleingang unten. Bei Route in den Fahrstuhl: Warte, bis das Knallgeräusch vom ankommenden Fahrstuhl direkt vor dir zu hören ist (maximal laut). Geh zum nächsten Punkt, der im Fahrstuhl ist. Fahr nur eine Etage hoch bis mitte unten. Geh dann geradeaus wieder aus dem Fahrstuhl raus zum Fahrstuhleingang mitte unten."] = "Entrée de l'ascenseur en bas. Si vous suivez un itinéraire vers l'ascenseur : attendez d'entendre le claquement de l'ascenseur qui arrive juste devant vous (volume maximum). Avancez jusqu'au point suivant, qui est dans l'ascenseur. Montez d'un étage jusqu'au milieu inférieur. Puis sortez tout droit de l'ascenseur jusqu'au point de passage entrée de l'ascenseur milieu inférieur.",
	["Achtung, gleich springen!"] = "Attention, vous devez sauter au prochain point de passage !",
	["Vorsicht! Nach Norden geht es über eine enge Brücke. Nach Osten geht es gegen den Urhzeigersinn an einer einem Schluchtrand entlang. Nach Westen geht es im Uhrzeigersinn am Schluchtrand entlang."] = "Attention ! Au sud vous traverserez un pont très étroit. À l'est vous longerez le bord d'un ravin. À l'ouest vous longerez également le bord d'un ravin.",
	["Benutze hier die Translokationskugel, um wieder nach unten zu kommen."] = "Utilisez la sphère de translocation ici pour redescendre.",
	["Benutze die Translokationskugel beim nächsten Wegpunkt um nach oben zu kommen."] = "Utilisez la sphère de translocation au prochain point de passage pour remonter.",
	["Für die Rückkehr nach unten, mache eine neue Route auf, mit dem Ziel das Portal Oben."] = "Pour redescendre, démarrez un nouvel itinéraire vers le portail supérieur.",
	["Töte die beiden Kerkermeister und öffne mit den Schlüsseln die Schlösser zu den Füssen der Gefangenen mit rechtklick. "] = "Tuez les deux geôliers et utilisez les clés pour ouvrir les serrures aux pieds des prisonniers par un clic droit.",
	["Moonglade"] = "Reflet-de-Lune",
	["Winterspring"] = "Berceau-de-l'Hiver",
	["h"] = "h",
	["Ironforge"] = "Forgefer",
	["Undercity"] = "Fossoyeuse",
	["s"] = "s",
	["Everlook"] = "Long-guet",
	["Stormwind"] = "Hurlevent",
	["moonglade"] = "Reflet-de-Lune",
	["Von hier 2 sekunden geradeaus laufen, um durch das portal zu gehen."] = "D'ici, avancez 1 seconde pour passer le portail.",
	["Von hier eine Sekunde geradeaus laufen, um durch das Portal zu gehen."] = "D'ici, avancez 1 seconde pour passer le portail.",
	["Stopp. Wenn du unter level 20 bist, und von menethil nach loch modan willst, bleib hier steht. Prüfe, ob vor dir ein mob ist. Wenn das der fall ist, warte hier bis dieser sich wegbewegt hat. laufe erst dann weiter! Solltest du trotzdem angegriffen werden, bleib nicht stehen. lauf weiter der route nach."] = "Stop. Si vous êtes en dessous du niveau 20 et voulez aller de Menethil au Loch Modan, arrêtez-vous ici. Vérifiez s'il y a une créature devant vous. Si c'est le cas, attendez ici qu'elle se soit éloignée et ne puisse plus être ciblée. Puis continuez ! Si vous êtes quand même attaqué, ne vous arrêtez pas : continuez à suivre l'itinéraire pour aller le plus loin possible avant de mourir.",
	["Von hier zurück an Land musst du extrem präsizes navigieren."] = "Vous devez naviguer très, très précisément pour sortir de l'eau.",
	["Achtung. Hier kommt ein Fahrstuhl ohne Geräusche nach oben. Um nach oben zu kommen, halte dich genau an die folgenden Schritte: Geh zum nächsten Wegpunkt. Nimm Akolyth der Aldor ins Ziel. Springe so lange immer wieder, bis sich die Entferung zum Ziel verändert. Laufe dann sofort vorwärts, bis du nicht mehr feststeckst. Dann bist oben und kannst zum nächsten Wegpunkt laufen."] = "Attention. Il y a ici un ascenseur silencieux. Pour monter, suivez exactement les étapes suivantes : descendez de monture ! Allez au point de passage suivant. Ciblez un Acolyte Aldor. Sautez sans arrêt jusqu'à ce que la distance à la cible change. Puis courez immédiatement en avant jusqu'à ne plus être bloqué. Vous êtes alors en haut et pouvez aller au point de passage suivant.",
	["Achtung. Hier kommt ein Fahrstuhl ohne Geräusche nach oben. Um nach oben zu kommen, halte dich genau an die folgenden Schritte: Nicht reiten! Geh zum nächsten Wegpunkt. Nimm Anhängerin der Seher ins Ziel. Springe so lange immer wieder, bis sich die Entferung zum Ziel verändert. Laufe dann sofort vorwärts, bis du nicht mehr feststeckst. Dann bist oben und kannst zum nächsten Wegpunkt laufen."] = "Attention. Il y a ici un ascenseur silencieux. Pour monter, suivez exactement les étapes suivantes : descendez de monture ! Allez au point de passage suivant. Ciblez un Serviteur clairvoyant. Sautez sans arrêt jusqu'à ce que la distance à la cible change. Puis courez immédiatement en avant jusqu'à ne plus être bloqué. Vous êtes alors en haut et pouvez aller au point de passage suivant.",
	["Nimm jetzt Akolyth der Aldor ins Ziel und geht zum nächsten Wegpunkt."] = "Ciblez maintenant un Acolyte Aldor et allez au point de passage suivant.",
	["Nimm jetzt Anhängerin der Seher ins Ziel und geht zum nächsten Wegpunkt."] = "Ciblez maintenant un Serviteur clairvoyant et allez au point de passage suivant.",
	["Springe so lange dauerhaft, bis sich die Entferung zum Ziel verändert. Laufe dann sofort vorwärts, bis du nicht mehr feststeckst."] = "Sautez sans arrêt jusqu'à ce que la distance à votre cible change. Puis courez immédiatement en avant jusqu'à ne plus être bloqué.",
	["Springe so lange, bis sich die Entferung zum Ziel verändert. Laufe dann sofort vorwärts, bis du nicht mehr feststeckst."] = "Sautez sans arrêt jusqu'à ce que la distance à votre cible change. Puis courez immédiatement en avant jusqu'à ne plus être bloqué.",
	["Achtung. Hier kommt ein Fahrstuhl ohne Geräusche nach unten. Du kannst nicht den Fahrstuhl nach unten nehmen. Suche nach dem Wegpunkt Shattrath Aldor oben nach unten und folge von dort einer Route nach unten."] = "Attention. Il y a ici un ascenseur silencieux. Vous ne pouvez pas le prendre pour descendre. Cherchez le point de passage Shattrath Aldor haut vers bas et suivez un itinéraire vers le bas à partir de là.",
	["Achtung. Hier kommt ein Fahrstuhl ohne Geräusche nach unten. Du kannst nicht den Fahrstuhl nach unten nehmen. Suche nach dem Wegpunkt Shattrath seher oben nach unten und folge von dort einer Route nach unten."] = "Attention. Il y a ici un ascenseur silencieux. Vous ne pouvez pas le prendre pour descendre. Cherchez le point de passage Shattrath clairvoyant haut vers bas et suivez un itinéraire vers le bas à partir de là.",
	["STOP! Von hier musst du sehr vorsichtig den Berg runter rutschen, um nach unten zu kommen. Navigiere 100% präzise! Wenn du fällst, heile oder verbinde dich, bevor du weiter läufst!"] = "STOP ! D'ici, vous devez avancer très, très prudemment pour descendre. Naviguez avec 100% de précision ! Si vous tombez, soignez-vous ou bandez-vous avant de continuer !",
	["Hier ist das untere Ende des Weges von der Aldor- und Seherhöhe nach unten. Er funktioniert nur runter. Du kommst hier nicht rauf. Nimm stattdessen eine Route zum Aldor- oder Seher-Fahrstuhl, wenn du rauf willst."] = "Ceci est le bas du chemin descendant depuis les hauteurs Aldor et clairvoyantes. Il ne fonctionne que vers le bas. Vous ne pouvez pas remonter ici. Prenez plutôt un itinéraire vers l'ascenseur Aldor ou clairvoyant si vous voulez monter.",
}
